@kbench.task(name="ves-label-synthetic-b")
def main_task(llm) -> float:
    runs = ves_item.evaluate(llm=[llm], evaluation_data=ROWS, n_jobs=2, on_failure="continue")
    for run in runs.errored_runs:
        print("ITEM_ERROR " + json.dumps({"params": str(run.params), "error": str(run.error_message)[:300]}))
    done = list(runs.completed_runs.as_dataframe().result)
    scored = [d for d in done if d["status"] != "infra"]
    infra = len(done) - len(scored)
    print("COMPLETED %d/%d  infra_failures=%d  errored=%d" % (len(done), len(ROWS), infra, len(runs.errored_runs)))
    if not scored:
        # No complete reply at all: record no score rather than a misleading 0.0.
        raise RuntimeError("no complete replies (%d infra failures); no score recorded" % infra)
    results = [{"item_id": d["item_id"], "rep": d["rep"], "status": d["status"], "pass": d["pass"]} for d in done]
    print("COUNTS " + json.dumps(condition_counts(ITEMS_BY_ID, results), sort_keys=True))
    if SCORE_MODE == "uncued_paired":
        # Leaderboard number: uncued paired pass rate, averaged over repeats (scoring/summary.py).
        print("RULE_PAIRED " + json.dumps(uncued_paired(ITEMS_BY_ID, results, prefix="rule")))
        value = uncued_paired(ITEMS_BY_ID, results)
        if value is None:
            raise RuntimeError("no complete uncued pairs; no score recorded")
        print("UNCUED_PAIRED " + json.dumps(value))
        return float(value)
    # Score: pass rate over items with a complete reply (infra failures excluded, reported above).
    return float(sum(d["pass"] for d in scored) / len(scored))
